  const values = await page.evaluate(() => ({
    mainCount: document.querySelectorAll('main').length,
    h1Count: document.querySelectorAll('h1').length,
    formFields: Array.from(document.querySelectorAll('.form-field')).length,
    phoneDesc: document.getElementById('phone-number').getAttribute('aria-describedby'),
    fullNameLabel: document.querySelector('label[for="full-name"]').textContent.trim(),
    emailRequired: document.getElementById('email-address').required,
    phoneRequired: document.getElementById('phone-number').required,
    initialErrors: Array.from(document.querySelectorAll('.error')).filter(el => !el.hidden).length
  }));

  console.log(JSON.stringify({ firstTab, values }, null, 2));
  await browser.close();
})();
