    <script>
      const h = (tag, props = {}, ...children) => {
        const el = document.createElement(tag);
        for (const [key, value] of Object.entries(props)) {
          if (key === "className") {
            el.className = value;
          } else if (key === "dataset") {
            Object.assign(el.dataset, value);
          } else if (key === "textContent") {
            el.textContent = value;
          } else if (key === "hidden") {
            el.hidden = value;
          } else if (key.startsWith("on") && typeof value === "function") {
            el.addEventListener(key.slice(2).toLowerCase(), value);
          } else if (value !== false && value !== null && value !== undefined) {
            el.setAttribute(key, value === true ? "" : value);
          }
        }
        for (const child of children.flat()) {
          if (child === null || child === undefined || child === false) continue;
          el.append(child.nodeType ? child : document.createTextNode(child));
        }
        return el;
      };

      function createField({ id, label, type, autocomplete, required, helperText }) {
        const errorId = `${id}-error`;
        const helpId = helperText ? `${id}-help` : null;
        const input = h("input", {
          id,
          name: id,
          type,
          autocomplete,
          ...(type === "email" ? { inputmode: "email" } : {}),
          ...(type === "tel" ? { inputmode: "tel" } : {}),
          ...(required ? { required: true } : {})
        });

        if (helpId) {
          input.setAttribute("aria-describedby", helpId);
        }

        const labelNode = h(
          "label",
          { for: id },
          label,
          required ? h("span", { className: "required-mark", "aria-hidden": "true" }, " *") : null
        );

        const field = h(
          "div",
          { className: "form-field" },
          labelNode,
          input,
          helperText ? h("p", { className: "help", id: helpId }, helperText) : null,
          h("p", { className: "error", id: errorId, hidden: true })
        );

        return { field, input, errorId, helpId };
      }

      function App() {
        const shell = h("section", { className: "shell" });
        shell.append(
          h(
            "div",
            { className: "hero" },
            h("h1", {}, "Contact support"),
            h(
              "p",
              { className: "lede" },
              "Send your details and we’ll route your request to the right team."
            )
          )
        );

        const card = h("div", { className: "card" });
        const form = h("form", { novalidate: true });
        const status = h("p", {
          className: "status",
          id: "form-status",
          "aria-live": "polite",
          "aria-atomic": "true",
          hidden: true
        });

        const fields = {
          fullName: createField({
            id: "full-name",
            label: "Full name",
            type: "text",
            autocomplete: "name",
            required: true
          }),
          email: createField({
            id: "email-address",
            label: "Email address",
            type: "email",
            autocomplete: "email",
            required: true
          }),
          phone: createField({
            id: "phone-number",
            label: "Phone number",
            type: "tel",
            autocomplete: "tel",
            required: false,
            helperText: "Format: +1 555 123 4567 or your local number with area code."
          })
        };

        function showError(field, message) {
          const errorNode = field.field.querySelector(".error");
          errorNode.textContent = `Error: ${message}`;
          errorNode.hidden = false;
          field.input.setAttribute("aria-invalid", "true");

          const ids = new Set(
            (field.input.getAttribute("aria-describedby") || "")
              .split(/\s+/)
              .filter(Boolean)
          );
          ids.add(errorNode.id);
          field.input.setAttribute("aria-describedby", Array.from(ids).join(" "));
        }

        function clearError(field) {
          const errorNode = field.field.querySelector(".error");
          errorNode.textContent = "";
          errorNode.hidden = true;
          field.input.removeAttribute("aria-invalid");

          const ids = (field.input.getAttribute("aria-describedby") || "")
            .split(/\s+/)
            .filter(Boolean)
            .filter((id) => id !== errorNode.id);
          if (ids.length) {
            field.input.setAttribute("aria-describedby", ids.join(" "));
          } else {
            field.input.removeAttribute("aria-describedby");
          }
        }

        function validateField(field) {
          const value = field.input.value.trim();
          if (field.input.required && !value) {
            showError(field, `Enter your ${field.input.name.replace("-", " ")}.`);
            return false;
          }

          if (field.input.type === "email" && value && !field.input.validity.valid) {
            showError(field, "Enter a valid email address, like name@example.com.");
            return false;
          }

          clearError(field);
          return true;
        }

        for (const field of Object.values(fields)) {
          field.input.addEventListener("input", () => {
            if (field.field.querySelector(".error").hidden) return;
            validateField(field);
          });
          field.input.addEventListener("blur", () => validateField(field));
        }

        form.addEventListener("submit", (event) => {
          const orderedFields = [fields.fullName, fields.email, fields.phone];
          const invalid = orderedFields.filter((field) => !validateField(field));
          if (invalid.length) {
            event.preventDefault();
            invalid[0].input.focus();
            status.hidden = true;
            status.textContent = "";
            return;
          }

          event.preventDefault();
          status.textContent = "Your details look good. Connect this form to your support endpoint to send it.";
          status.hidden = false;
        });

        form.append(
          fields.fullName.field,
          fields.email.field,
          fields.phone.field,
          h(
            "div",
            { className: "actions" },
            h("button", { type: "submit" }, "Send message")
          ),
          status
        );

        card.append(form);
        shell.append(card);
        return shell;
      }

      document.getElementById("maincontent").append(App());
    </script>
